func squares(ctx context.Context, in <-chan int) (<-chan int, <-chan error) {
    out := make(chan int)
    go func() {
        defer close(out)
        for n := range in {
            select {
            case out <- n * n:
            case <-ctx.Done():
                return
            }
        }
    }()
    return out, nil
}
